// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"ko","term":"완전 희석 가치(FDV)","aka":["FDV","완전희석 시가총액","Fully Diluted Valuation"],"short":"완전 희석 가치(FDV)는 코인의 현재 가격에 앞으로 발행될 물량까지 포함한 최대 또는 총 공급량을 곱한 값으로, 모든 토큰이 풀렸을 때의 평가 규모를 보여 줍니다.","body":[[["시가총액","market-capitalization"],"이 지금 유통 중인 물량만 계산한다면, FDV는 아직 잠겨 있거나 발행되지 않은 물량까지 모두 포함합니다. 계산식은 현재 가격 곱하기 최대 공급량(또는 총공급량)입니다. 데이터 사이트마다 어느 공급량을 기준으로 삼는지 조금씩 다릅니다."],"FDV와 시가총액의 차이가 크다는 것은 앞으로 시장에 나올 물량이 많다는 뜻입니다. 팀, 투자자, 생태계 기금 물량이 순차적으로 언락되면 같은 수요에서도 공급이 늘어나 가격에 부담이 될 수 있습니다.",["특히 ",["신규 상장","token-listing"]," 코인은 ",["유통량","circulating-supply"],"이 전체의 10~20% 수준인 경우도 있어, 시가총액은 작아 보여도 FDV는 매우 클 수 있습니다. 그래서 신규 코인을 볼 때는 시가총액, FDV, 언락 일정을 함께 확인하는 습관이 필요합니다."]],"example":"어떤 신규 코인의 가격이 2달러이고 유통량이 1억 개, 최대 공급량이 10억 개라고 가정합니다. 시가총액은 2억 달러지만 FDV는 20억 달러입니다. 남은 9억 개가 모두 풀릴 때 FDV와 같은 20억 달러 평가를 유지하려면 지금의 시가총액보다 10배 큰 자금이 필요하다는 뜻입니다. 시가총액 대비 FDV 비율이 10배라는 점이 핵심 체크 포인트입니다.","mistakes":["시가총액만 보고 저평가라고 판단하며 FDV와의 격차를 확인하지 않습니다.","FDV를 미래 목표 가격처럼 해석합니다.","최대 공급량이 없는 코인에도 FDV가 정확히 계산된다고 생각합니다."],"faq":[{"q":"FDV와 시가총액의 차이는 무엇인가요?","a":"시가총액은 유통 중인 물량만, FDV는 앞으로 나올 물량까지 포함해 계산합니다. 둘의 차이가 클수록 향후 추가 공급이 많다는 뜻입니다."},{"q":"FDV가 높으면 나쁜 코인인가요?","a":"그 자체로 좋고 나쁨을 말할 수는 없습니다. 다만 유통 비율이 낮고 언락이 빠르게 진행된다면 공급 증가에 따른 매도 압력을 고려해야 합니다."}],"title":"FDV(완전 희석 가치)란? 시가총액과 차이","description":"FDV(완전 희석 가치)의 뜻과 계산법, 시가총액과의 차이, 신규 코인에서 유통 비율과 언락 일정을 함께 봐야 하는 이유를 설명합니다.","related":[["market-capitalization","시가총액(Market Cap)","시가총액은 코인의 현재 가격에 유통 공급량을 곱한 값으로, 시장이 그 자산 전체를 얼마로 평가하고 있는지 보여 주는 지표입니다."],["circulating-supply","유통량(Circulating Supply)","유통량은 현재 시장에서 실제로 거래될 수 있는 코인의 수량으로, 잠겨 있거나 아직 발행되지 않은 물량은 제외합니다."],["token-unlock","토큰 언락(Token Unlock)","토큰 언락은 팀, 투자자, 생태계 기금 등에게 배분된 뒤 잠겨 있던 토큰이 정해진 일정에 따라 풀려 거래 가능한 상태가 되는 것입니다."],["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"ko","term":"채굴(Crypto Mining)","aka":["마이닝","Mining","코인 채굴"],"short":"채굴은 작업증명 블록체인에서 컴퓨터 연산으로 새 블록을 만들고 거래를 확정하는 과정으로, 채굴자는 그 대가로 블록 보상과 거래 수수료를 받습니다.","body":["채굴자는 거래를 모아 블록 후보를 만들고, 조건에 맞는 해시값을 찾을 때까지 계산을 반복합니다. 먼저 찾은 채굴자가 블록을 추가하고 새로 발행되는 코인과 그 블록에 포함된 수수료를 받습니다. 이 과정이 네트워크 보안을 유지합니다.",[["비트코인","bitcoin"]," 채굴은 ASIC이라는 전용 장비로 이루어지며, 개인보다는 전기료가 저렴한 지역의 대규모 채굴장이 대부분을 차지합니다. 혼자 블록을 찾을 확률이 매우 낮아서 여러 채굴자가 ",["해시레이트","hash-rate"],"를 모아 보상을 나누는 채굴 풀에 참여하는 것이 일반적입니다."],["채굴 수익은 코인 가격, 네트워크 난이도, 전기료, 장비 효율, ",["반감기","bitcoin-halving"]," 일정에 따라 크게 달라집니다. 클라우드 채굴이라는 이름으로 높은 수익을 약속하는 상품 중에는 사기도 많으니 운영 주체와 계약 구조를 꼼꼼히 확인해야 합니다."]],"example":"채굴기 한 대가 하루에 0.0001 BTC를 벌고, 전력 3 kW를 24시간 쓴다고 가정해 보겠습니다. 하루 전력 사용량은 72 kWh이고 전기료가 kWh당 100원이면 하루 전기료는 7,200원입니다. BTC 가격이 1억 원이라면 하루 채굴 수입은 1만 원이라 차익은 2,800원입니다. 가격이 30% 떨어지면 수입은 7,000원으로 줄어 오히려 적자가 됩니다.","mistakes":["채굴 수익을 계산할 때 전기료와 장비 감가상각을 빼먹습니다.","이더리움처럼 지분증명으로 전환한 코인도 여전히 채굴할 수 있다고 믿습니다.","원금 보장과 고정 수익을 약속하는 클라우드 채굴 상품을 검증 없이 가입합니다."],"faq":[{"q":"개인이 집에서 비트코인을 채굴할 수 있나요?","a":"기술적으로는 가능하지만 전용 장비 비용과 전기료를 고려하면 수익을 내기 어려운 경우가 많습니다. 전기료가 매우 저렴한 환경이 아니라면 신중하게 계산해야 합니다."},{"q":"채굴 풀은 무엇인가요?","a":"여러 채굴자가 연산력을 모아 블록을 함께 찾고, 기여한 해시레이트 비율에 따라 보상을 나누는 방식입니다. 수익이 더 꾸준해지는 대신 풀 수수료가 붙습니다."}],"title":"코인 채굴이란? 뜻과 채굴 수익 구조","description":"암호화폐 채굴의 뜻과 원리, 채굴 풀과 ASIC 장비, 전기료와 가격 변동이 채굴 수익에 미치는 영향을 계산 예시로 설명합니다.","related":[["proof-of-work","작업증명(Proof of Work, PoW)","작업증명(PoW)은 채굴자가 대량의 연산으로 특정 조건을 만족하는 해시값을 먼저 찾아내야 블록을 추가할 수 있게 하는 블록체인 합의 방식입니다."],["hash-rate","해시레이트(Hash rate)","해시레이트는 작업증명 블록체인에서 채굴 장비들이 1초에 계산하는 해시의 총량으로, 네트워크의 채굴 경쟁 강도와 보안 수준을 보여 주는 지표입니다."],["bitcoin-halving","비트코인 반감기(Halving)","비트코인 반감기는 21만 블록(약 4년)마다 채굴 보상이 절반으로 줄어드는 프로토콜 규칙으로, 새 비트코인의 발행 속도를 낮춥니다."],["blockchain","블록체인(Blockchain)","블록체인은 거래 기록을 블록 단위로 묶어 시간 순서대로 연결하고, 여러 컴퓨터가 같은 사본을 나눠 보관하는 분산 장부입니다."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"ko","term":"검증자(Validator)","aka":["밸리데이터","Validator","검증인"],"short":"검증자는 지분증명 블록체인에서 코인을 예치하고 노드를 운영하며 새 블록을 제안하고 다른 블록을 검증해 보상을 받는 참여자입니다.","body":[["검증자는 네트워크 규칙에 맞게 거래가 처리됐는지 확인하고, 순서가 오면 새 블록을 제안합니다. ",["이더리움","ethereum"],"에서 검증자를 직접 운영하려면 32 ETH를 예치하고 항상 온라인 상태인 ",["노드","node"],"를 유지해야 합니다."],"검증자가 오프라인 상태로 업무를 놓치면 보상이 줄거나 작은 페널티를 받고, 이중 서명처럼 심각한 위반을 하면 예치금이 삭감되는 슬래싱을 당할 수 있습니다. 그래서 서버 관리 능력과 안정적인 인프라가 중요합니다.",["대부분의 사용자는 직접 검증자를 운영하지 않고 ",["거래소","centralized-exchange"]," ",["스테이킹","staking"],", 위임, ",["리퀴드 스테이킹","liquid-staking"]," 서비스를 통해 간접적으로 참여합니다. 이때는 검증자 운영자의 수수료와 신뢰도, 슬래싱 발생 시 손실 분담 방식을 확인해야 합니다."]],"example":"어떤 체인에서 검증자에게 위임하는 상황을 생각해 보겠습니다. 2,000개 코인을 위임했고 네트워크 연간 보상률이 6%, 검증자 수수료가 8%라고 가정합니다. 총보상은 120개이고 수수료 9.6개를 제외하면 실수령은 110.4개입니다. 만약 검증자가 슬래싱으로 예치금의 1%를 잃는 규칙이 적용되면 위임한 2,000개 중 20개가 줄어들 수 있습니다.","mistakes":["수수료가 가장 낮은 검증자만 고르고 가동률과 운영 이력은 확인하지 않습니다.","위임하면 코인 소유권이 검증자에게 넘어간다고 오해하거나, 반대로 아무 위험이 없다고 생각합니다.","언본딩 기간 동안에는 코인을 팔 수 없다는 점을 모르고 위임합니다."],"faq":[{"q":"검증자와 채굴자는 무엇이 다른가요?","a":"채굴자는 작업증명 체인에서 연산력으로, 검증자는 지분증명 체인에서 예치한 코인으로 블록 생성에 참여합니다. 역할은 비슷하지만 자격을 얻는 방식이 다릅니다."},{"q":"이더리움 검증자가 되려면 무엇이 필요한가요?","a":"단독으로 운영하려면 32 ETH와 항상 켜져 있는 노드 환경이 필요합니다. 그보다 적은 금액은 스테이킹 풀이나 거래소 상품을 통해 참여할 수 있습니다."}],"title":"검증자(Validator)란? 뜻과 역할 정리","description":"검증자(밸리데이터)의 뜻과 역할, 이더리움 32 ETH 기준, 슬래싱 위험과 위임 시 수수료·언본딩 기간을 정리합니다.","related":[["proof-of-stake","지분증명(Proof of Stake, PoS)","지분증명(PoS)은 코인을 담보로 예치한 검증자가 블록을 제안하고 검증할 자격을 얻는 블록체인 합의 방식으로, 채굴 장비 대신 예치한 지분이 보안의 근거가 됩니다."],["staking","스테이킹(Staking)","스테이킹은 지분증명(PoS) 블록체인에서 코인을 맡겨 네트워크 검증에 참여하거나 검증인에게 위임하고 그 대가로 보상을 받는 방법입니다."],["restaking","리스테이킹(Restaking)","리스테이킹은 이미 스테이킹한 ETH나 리퀴드 스테이킹 토큰을 다른 서비스의 보안에도 다시 담보로 제공해 추가 보상을 받는 구조입니다."],["blockchain","블록체인(Blockchain)","블록체인은 거래 기록을 블록 단위로 묶어 시간 순서대로 연결하고, 여러 컴퓨터가 같은 사본을 나눠 보관하는 분산 장부입니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"ko","term":"거래 페어(Trading Pair)","aka":["마켓","거래쌍","페어"],"short":"거래 페어는 어떤 코인을 어떤 자산으로 사고파는지를 나타내는 조합으로, BTC/USDT는 BTC를 USDT로 거래한다는 뜻입니다.","body":[["거래 페어에서 앞쪽은 기초 자산, 뒤쪽은 가격을 매기는 견적 자산입니다. ",["BTC","bitcoin"],"/",["USDT","usdt"]," 가격이 60,000이라면 1 BTC를 사는 데 60,000 USDT가 든다는 의미입니다. 국내 ",["거래소","centralized-exchange"],"에서는 원화마켓, BTC마켓, USDT마켓처럼 견적 자산별로 마켓을 나눠 보여 줍니다."],["같은 코인이라도 페어마다 ",["유동성","liquidity"],"이 다릅니다. 보통 USDT 페어나 원화 페어가 ",["거래량","trading-volume"],"이 많아 호가가 촘촘하고 ",["스프레드","bid-ask-spread"],"가 좁습니다. 거래량이 적은 페어에서는 시장가 주문 시 슬리피지가 커질 수 있습니다."],"직접 페어가 없으면 중간 자산을 거쳐야 합니다. 예를 들어 A 코인을 B 코인으로 바꾸려는데 A/B 페어가 없다면 A를 USDT로 팔고 그 USDT로 B를 사야 하므로 수수료를 두 번 냅니다."],"example":"SOL/USDT 페어 가격이 150이고 BTC/USDT가 60,000이라고 가정해 보겠습니다. SOL/BTC 페어 가격은 이론상 150 나누기 60,000, 즉 0.0025 BTC입니다. 10 SOL을 BTC로 바꿀 때 SOL/BTC 페어가 있으면 한 번에 0.025 BTC를 받고, 없다면 SOL을 1,500 USDT로 판 뒤 다시 BTC를 사야 합니다. 수수료가 0.1%씩 두 번 붙으면 비용은 약 0.2%가 됩니다.","mistakes":["BTC 마켓 가격을 원화나 USDT 가격으로 착각해 주문 금액을 잘못 계산합니다.","거래량이 적은 페어에서 큰 금액을 시장가로 체결합니다.","같은 코인의 페어별 가격 차이를 확인하지 않고 불리한 페어에서 거래합니다."],"faq":[{"q":"BTC/USDT에서 앞과 뒤는 무엇을 뜻하나요?","a":"앞의 BTC는 사고파는 대상(기초 자산), 뒤의 USDT는 가격을 표시하는 화폐(견적 자산)입니다. 가격은 1 BTC당 USDT 수량으로 표시됩니다."},{"q":"원화마켓과 USDT마켓 가격이 다른 이유는 무엇인가요?","a":"각 마켓의 수요와 공급, 환율, 국내외 시세 차이(김치 프리미엄) 등이 반영되기 때문입니다. 같은 코인이라도 마켓에 따라 체결 가격이 다를 수 있습니다."}],"title":"거래 페어란? BTC/USDT 뜻과 읽는 법","description":"거래 페어(마켓)의 뜻과 BTC/USDT 읽는 법, 원화·USDT·BTC 마켓의 차이, 페어별 유동성과 수수료 차이를 설명합니다.","related":[["spot-trading","현물 거래(Spot Trading)","현물 거래는 코인을 현재 가격에 실제로 사고팔아 즉시 소유권이 넘어가는 거래 방식으로, 산 코인은 바로 내 계정 잔고에 들어옵니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"첫 현물 거래: 100에서 0.002 BTC까지"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"ko","term":"OCO 주문(One-Cancels-the-Other)","aka":["OCO","양방향 주문","OCO 주문"],"short":"OCO 주문은 두 개의 주문을 묶어 하나가 체결되면 나머지 하나가 자동으로 취소되도록 하는 주문 방식으로, 익절과 손절을 동시에 걸 때 주로 씁니다.","body":[["OCO는 One-Cancels-the-Other의 약자입니다. 보통 ",["현재가","last-price"]," 위에 ",["지정가","limit-order"]," ",["익절 주문","take-profit"],"을, 현재가 아래에 스탑 리밋 ",["손절 주문","stop-loss"],"을 함께 걸어 둡니다. 가격이 위로 가면 익절이, 아래로 가면 손절이 실행되고 반대쪽 주문은 사라집니다."],"OCO가 없으면 익절과 손절을 각각 걸어야 하는데, 현물에서는 같은 코인 수량이 두 주문에 동시에 묶일 수 없어 하나만 걸 수 있는 경우가 많습니다. OCO는 이 문제를 해결해 수량 하나로 양방향 계획을 세울 수 있게 해 줍니다.",["선물 거래에서는 포지션에 TP/SL을 함께 설정하는 기능이 비슷한 역할을 합니다. OCO를 지원하는지, 어떤 주문 조합이 가능한지는 ",["거래소","centralized-exchange"],"마다 다르므로 주문 화면에서 확인해야 합니다."]],"example":[["ETH","ethereum"]," 2개를 3,000 USDT에 산 뒤 OCO 매도를 설정한다고 가정해 보겠습니다. 익절 지정가는 3,300 USDT, 손절은 트리거 2,850 USDT, 지정가 2,840 USDT로 둡니다. 가격이 3,300 USDT에 도달하면 2 ETH가 팔려 600 USDT 이익이 나고 손절 주문은 자동 취소됩니다. 반대로 2,850 USDT에 닿으면 2,840 USDT 이상에서 팔려 손실은 최대 320 USDT이며 익절 주문은 취소됩니다."],"mistakes":["OCO의 손절 쪽 스탑 리밋 간격을 너무 좁게 잡아 급락 시 체결되지 않습니다.","익절과 손절을 OCO 없이 따로 걸려다 잔고 부족으로 한쪽 주문이 거절됩니다.","OCO가 체결된 뒤 남은 주문이 정말 취소됐는지 확인하지 않습니다."],"faq":[{"q":"OCO 주문은 어디서 쓸 수 있나요?","a":"여러 해외 거래소가 현물에서 OCO 주문을 제공합니다. 지원 여부와 세부 방식은 거래소마다 다르므로 주문 유형 목록을 확인해야 합니다."},{"q":"OCO와 TP/SL의 차이는 무엇인가요?","a":"둘 다 익절과 손절을 함께 거는 목적이지만, OCO는 주로 현물에서 두 주문을 묶는 방식이고 TP/SL은 선물 포지션에 붙는 설정인 경우가 많습니다."}],"title":"OCO 주문이란? 익절·손절 동시 설정법","description":"OCO 주문의 뜻과 작동 방식, 현물에서 익절과 손절을 한 번에 거는 방법, TP/SL과의 차이를 계산 예시로 설명합니다.","related":[["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."],["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."],["risk-reward-ratio","손익비(Risk-Reward Ratio)","손익비는 한 번의 거래에서 감수하는 손실 폭(진입가와 손절가의 차이)과 기대하는 수익 폭(진입가와 익절가의 차이)을 비교한 비율입니다."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"시장가, 지정가, 취소: 각각 무엇을 해결하는가?"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"ko","term":"포스트 온리 주문(Post-Only)","aka":["Post-Only","메이커 온리","포스트온리"],"short":"포스트 온리 주문은 반드시 호가창에 대기 주문으로 올라가는 지정가 주문으로, 즉시 체결될 상황이면 자동으로 취소되어 항상 메이커로만 체결되게 합니다.","body":[["일반 ",["지정가 주문","limit-order"],"은 현재 호가와 바로 맞으면 즉시 체결되어 ",["테이커 수수료","maker-taker-fees"],"가 붙습니다. 포스트 온리 옵션을 켜면 이런 경우 주문이 체결되지 않고 취소되므로, 체결된다면 항상 메이커 수수료가 적용됩니다."],["메이커와 테이커 수수료 차이가 있는 ",["거래소","centralized-exchange"],"에서 자주 거래하는 사람, 특히 그리드나 마켓메이킹처럼 주문을 많이 내는 전략에서 비용 절감 효과가 큽니다. 일부 거래소에서는 일정 등급 이상에서 메이커 수수료가 매우 낮거나 리베이트가 주어지기도 합니다."],"단점은 체결 기회를 놓칠 수 있다는 것입니다. 가격이 빠르게 움직이면 주문이 계속 취소되어 원하는 포지션을 잡지 못할 수 있습니다. 급하게 진입하거나 손절해야 할 때는 적합하지 않습니다."],"example":["한 달에 현물로 총 200,000 USDT를 거래한다고 가정해 보겠습니다. 메이커 수수료가 0.08%, 테이커 수수료가 0.1%라면 모두 테이커로 체결할 때 수수료는 200 ",["USDT","usdt"],", 모두 메이커로 체결하면 160 USDT입니다. 포스트 온리로 메이커 체결을 지키면 한 달에 40 USDT, 1년이면 480 USDT를 아낄 수 있습니다. 실제 수수료율은 거래소와 등급마다 다릅니다."],"mistakes":["현재 매도 호가보다 높은 가격에 포스트 온리 매수를 넣고 주문이 취소된 이유를 모릅니다.","급한 손절이나 청산 회피 상황에서 포스트 온리를 사용합니다.","수수료 절감만 보고 체결되지 않아 놓친 기회 비용은 계산하지 않습니다."],"faq":[{"q":"포스트 온리 주문이 취소되는 이유는 무엇인가요?","a":"주문 가격이 현재 상대 호가와 바로 맞아 즉시 체결될 상황이었기 때문입니다. 포스트 온리는 테이커가 되는 것을 막기 위해 이런 주문을 자동 취소합니다."},{"q":"포스트 온리는 어떤 사람에게 유용한가요?","a":"거래 빈도가 높고 급하게 체결할 필요가 없는 사람에게 유용합니다. 메이커 수수료를 꾸준히 적용받아 누적 거래 비용을 줄일 수 있습니다."}],"title":"포스트 온리 주문이란? 메이커 전용 주문 뜻","description":"포스트 온리(Post-Only) 주문의 뜻과 작동 방식, 메이커 수수료를 지키는 원리, 주문이 취소되는 이유를 예시로 설명합니다.","related":[["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."],["time-in-force","주문 유효 조건(Time in Force: GTC, IOC, FOK)","주문 유효 조건(Time in Force)은 주문이 체결되지 않았을 때 얼마나 오래 유지할지와 일부 체결을 허용할지를 정하는 설정으로, GTC, IOC, FOK가 대표적입니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"시장가, 지정가, 취소: 각각 무엇을 해결하는가?"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"ko","term":"메이커·테이커 수수료(Maker/Taker Fee)","aka":["메이커 수수료","테이커 수수료","maker taker fee"],"short":"메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다.","body":[[["지정가 주문","limit-order"],"을 넣었는데 바로 체결되지 않고 ",["호가창","order-book"],"에 남아 있다가 나중에 체결되면 메이커로 분류됩니다. 반대로 ",["시장가 주문","market-order"],"이나 현재 호가에 바로 닿는 지정가 주문은 호가창의 물량을 가져가므로 테이커가 됩니다."],["대부분의 ",["거래소","centralized-exchange"],"는 ",["유동성","liquidity"],"을 늘려 주는 메이커에게 더 낮은 수수료를 받습니다. ",["거래량","trading-volume"],"이 많아질수록 등급(VIP 티어)이 올라가 두 수수료가 모두 내려가는 구조가 일반적이며, 일부 거래소는 높은 등급의 메이커에게 리베이트를 주기도 합니다."],"현물과 선물, 거래소마다 요율 체계가 다르므로 실제 비율은 이용하는 거래소의 수수료 안내 페이지에서 확인해야 합니다. 자주 매매할수록 메이커 비중을 높이는 것만으로 비용 차이가 크게 벌어집니다."],"example":"예를 들어 메이커 수수료가 0.02%, 테이커 수수료가 0.05%인 선물 계정에서 10,000 USDT 규모 포지션을 진입하고 청산한다고 가정해 보겠습니다. 진입과 청산을 모두 시장가로 하면 10,000 × 0.05% × 2 = 10 USDT를 냅니다. 둘 다 지정가로 걸어 메이커로 체결되면 10,000 × 0.02% × 2 = 4 USDT입니다. 한 달에 이런 거래를 50번 하면 차이는 300 USDT가 됩니다.","mistakes":["지정가 주문이면 무조건 메이커 수수료가 적용된다고 생각하지만, 현재가에 바로 체결되는 지정가는 테이커로 처리됩니다.","수수료율만 보고 레버리지 포지션의 실제 비용을 계산하지 않아, 증거금이 아니라 포지션 전체 금액에 수수료가 붙는다는 점을 놓칩니다.","펀딩비나 출금 수수료 같은 다른 비용을 빼고 메이커·테이커 수수료만 비교해 거래소를 고릅니다."],"faq":[{"q":"메이커와 테이커는 어떻게 구분하나요?","a":"주문이 호가창에 먼저 올라가 다른 사람의 주문을 기다렸다면 메이커, 이미 있는 주문을 바로 가져가 체결됐다면 테이커입니다. 체결 내역에서 거래소가 표시해 주는 경우가 많습니다."},{"q":"항상 메이커로 체결되게 하는 방법이 있나요?","a":"포스트 온리(Post-only) 옵션을 켜면 즉시 체결될 주문은 자동 취소되어 메이커로만 체결됩니다. 대신 가격이 빠르게 움직이면 주문이 체결되지 않을 수 있습니다."}],"title":"메이커·테이커 수수료란? 차이와 계산법","description":"메이커와 테이커 수수료의 차이, 지정가·시장가 주문과의 관계, 거래 비용을 줄이는 계산 방법을 예시로 설명합니다.","related":[["post-only-order","포스트 온리 주문(Post-Only)","포스트 온리 주문은 반드시 호가창에 대기 주문으로 올라가는 지정가 주문으로, 즉시 체결될 상황이면 자동으로 취소되어 항상 메이커로만 체결되게 합니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다."],["vip-tier","VIP 수수료 등급","VIP 수수료 등급은 거래소가 최근 거래량이나 보유 자산 규모에 따라 사용자를 단계별로 나누고 높은 등급일수록 낮은 메이커·테이커 수수료를 적용하는 제도입니다."],["referral-code","레퍼럴 코드(수수료 페이백)","레퍼럴 코드는 거래소 가입 시 입력하는 추천 코드로, 연결된 계정의 거래 수수료 일부를 사용자에게 할인이나 페이백 형태로 돌려주는 데 쓰입니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"ko","term":"유지 증거금(Maintenance Margin)","aka":["유지 마진","maintenance margin","MM"],"short":"유지 증거금은 레버리지 포지션을 계속 유지하기 위해 계좌에 남아 있어야 하는 최소 증거금으로, 증거금이 이 수준 아래로 떨어지면 강제청산이 시작됩니다.","body":[["유지 증거금은 보통 포지션 규모에 유지 증거금률을 곱해 계산합니다. 예를 들어 유지 증거금률이 0.5%라면 10,000 ",["USDT","usdt"]," 포지션에는 50 USDT의 유지 증거금이 필요합니다."],["평가 손실이 커지면 포지션의 증거금 잔액이 줄어듭니다. 잔액이 유지 증거금 이하로 내려가면 ",["거래소","centralized-exchange"],"는 손실이 더 커지기 전에 포지션을 정리합니다. 이 판단은 보통 ",["최근 체결가","last-price"],"가 아닌 ",["마크 가격","mark-price"],"을 기준으로 합니다."],["유지 증거금률은 종목과 포지션 규모에 따라 단계별로 다르며, 포지션이 클수록 높아집니다. ",["격리 마진","isolated-margin"],"에 증거금을 추가하거나 포지션 일부를 줄이면 ",["청산가","liquidation-price"],"를 진입가에서 더 멀리 밀어낼 수 있습니다."]],"example":"1,000 USDT 증거금, 10배 레버리지로 10,000 USDT 규모 BTC 롱을 열고 유지 증거금률이 0.5%라고 가정해 보겠습니다. 유지 증거금은 50 USDT입니다. 손실이 950 USDT에 이르면 남은 증거금이 50 USDT가 되어 청산 기준에 닿습니다. 950 ÷ 10,000 = 9.5%이므로 BTC가 진입가보다 약 9.5% 떨어지면 청산됩니다. 수수료는 계산에서 뺐습니다.","mistakes":["증거금이 0이 될 때 청산된다고 생각해 실제 청산가를 진입가에서 더 먼 곳으로 착각합니다.","포지션 규모를 키우면 유지 증거금률도 올라간다는 단계별 구조를 모릅니다.","최근 체결가만 보고 아직 여유가 있다고 판단하지만, 청산은 마크 가격 기준으로 일어납니다."],"faq":[{"q":"유지 증거금 아래로 떨어지면 바로 청산되나요?","a":"대부분의 거래소에서 마크 가격 기준으로 유지 증거금 이하가 되면 청산 절차가 바로 시작됩니다. 일부 거래소는 일부만 먼저 줄이는 부분 청산을 하기도 합니다."},{"q":"청산을 피하려면 어떻게 하나요?","a":"증거금을 추가하거나 포지션 일부를 줄여 유지 증거금 대비 여유를 늘립니다. 애초에 낮은 레버리지와 손절가를 정해 두는 것이 가장 확실합니다."}],"title":"유지 증거금이란? 청산 기준 계산법","description":"선물 거래의 유지 증거금 뜻, 유지 증거금률로 청산 시점을 계산하는 방법, 청산을 피하는 법을 설명합니다.","related":[["initial-margin","초기 증거금(Initial Margin)","초기 증거금은 레버리지 포지션을 새로 열 때 담보로 맡겨야 하는 최소 금액으로, 보통 포지션 규모를 레버리지 배수로 나눈 값입니다."],["liquidation-price","청산가(Liquidation Price)","청산가는 마크 가격이 그 수준에 닿으면 증거금이 유지 증거금 아래로 떨어져 포지션이 강제청산되는 가격입니다."],["margin-call","마진콜(Margin Call)","마진콜은 손실로 증거금이 줄어 청산 기준에 가까워졌을 때 증거금을 추가하거나 포지션을 줄이라고 알리는 경고입니다."],["mark-price","마크 가격(Mark Price)","마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"증거금이 제로가 되기 전에 강제 종료될 수 있는 이유는?"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"ko","term":"리듀스 온리 주문(Reduce-Only)","aka":["리듀스 온리","포지션 감소 전용","reduce-only","감소 전용 주문"],"short":"리듀스 온리 주문은 기존 포지션을 줄이거나 닫는 데만 쓰이고, 포지션을 늘리거나 반대 방향 포지션을 새로 열지 않도록 제한된 주문 옵션입니다.","body":[[["롱 포지션","long-and-short"],"에 익절용 매도 ",["지정가","limit-order"],"를 걸어 두었는데, 그 전에 수동으로 포지션을 닫았다고 가정해 보겠습니다. 일반 주문이라면 나중에 그 매도 주문이 체결되며 원하지 않는 숏 포지션이 생길 수 있습니다. 리듀스 온리를 켜 두면 포지션이 없을 때 이 주문이 체결되지 않거나 자동 취소됩니다."],"주문 수량이 현재 포지션보다 크면 포지션 수량만큼만 체결되도록 줄어드는 경우가 많습니다. 익절, 손절, 분할 청산 주문에 습관적으로 켜 두면 실수를 크게 줄일 수 있습니다.",[["거래소","centralized-exchange"],"에 따라 손절·익절 전용 주문에는 리듀스 온리가 자동 적용되기도 하고, 양방향 모드에서는 포지션 닫기 주문이 별도로 구분되기도 합니다. 단방향 모드에서 일반 지정가로 청산 주문을 걸 때 특히 중요합니다."]],"example":[["BTC","bitcoin"]," 롱 0.3 BTC를 들고 있고, 68,000 USDT에 0.3 BTC 매도 지정가를 익절용으로 걸어 두었다고 가정해 보겠습니다. 가격이 66,000 USDT일 때 마음이 바뀌어 ",["시장가","market-order"],"로 포지션을 모두 닫았습니다. 리듀스 온리가 없으면 나중에 68,000에 매도가 체결되며 0.3 BTC 숏, 약 20,400 ",["USDT","usdt"]," 규모 포지션이 새로 생깁니다. 리듀스 온리를 켜 두었다면 이 주문은 체결되지 않고 취소됩니다."],"mistakes":["익절용 지정가 주문에 리듀스 온리를 켜지 않아 포지션을 닫은 뒤 의도치 않은 반대 포지션이 열립니다.","리듀스 온리 주문이 포지션보다 큰 수량으로도 전부 체결된다고 생각합니다.","양방향 모드와 단방향 모드에서 청산 주문 방식이 다르다는 점을 확인하지 않습니다."],"faq":[{"q":"리듀스 온리는 언제 켜야 하나요?","a":"포지션을 줄이거나 닫으려는 모든 주문, 특히 미리 걸어 두는 익절과 분할 청산 지정가에 켜 두는 것이 안전합니다."},{"q":"리듀스 온리 주문이 취소되는 이유는 무엇인가요?","a":"포지션이 이미 닫혔거나 주문이 포지션을 늘리는 방향이면 거래소가 주문을 거부하거나 취소합니다. 이것이 바로 리듀스 온리의 보호 기능입니다."}],"title":"리듀스 온리 주문이란? 사용법과 예시","description":"선물 리듀스 온리(포지션 감소 전용) 주문의 뜻, 의도치 않은 반대 포지션을 막는 원리와 사용법을 설명합니다.","related":[["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."],["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["long-and-short","롱과 숏(Long and Short)","롱은 가격이 오를 것으로 보고 매수해 상승 시 이익을 얻는 포지션이고, 숏은 가격이 내릴 것으로 보고 매도해 하락 시 이익을 얻는 포지션입니다."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"익절과 손절은 계획이지 보험이 아니다"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"ko","term":"지갑 주소(Wallet Address)","aka":["입금 주소","코인 주소","wallet address"],"short":"지갑 주소는 블록체인에서 코인을 받을 때 쓰는 문자열로, 은행 계좌번호처럼 다른 사람에게 알려 줘도 되는 수신용 식별자입니다.","body":[["체인마다 주소 형식이 다릅니다. ",["비트코인","bitcoin"]," 주소는 1, 3, bc1로 시작하고, ",["이더리움","ethereum"],"과 BNB 체인, 아비트럼 같은 EVM 계열은 0x로 시작하는 42자, 트론은 T로 시작합니다. ",["거래소","centralized-exchange"]," 입금 화면에서는 코인과 네트워크를 고른 뒤 그에 맞는 주소를 받습니다."],[["블록체인","blockchain"]," 송금은 취소가 없습니다. 한 글자라도 틀리거나 다른 사람의 주소로 보내면 되돌리기 어렵습니다. 같은 0x 주소라도 네트워크를 잘못 고르면 다른 체인으로 가 버릴 수 있다는 점도 주의해야 합니다."],["주소는 복사해 붙여 넣는 것이 기본이고, 붙여 넣은 뒤에는 앞뒤 몇 글자를 원래 주소와 대조합니다. 자주 쓰는 주소는 ",["출금 화이트리스트","withdrawal-whitelist"],"에 등록해 두면 실수를 줄일 수 있습니다."]],"example":["거래소에서 ",["개인 지갑","non-custodial-wallet"],"으로 800 USDT를 처음 보낸다고 가정합니다. 먼저 10 USDT만 테스트로 보내고 지갑에 도착했는지 확인합니다. 출금 수수료가 1 USDT라면 테스트에 11 USDT가 들고, 남은 789 USDT 가운데 788 USDT를 보내면 수수료 1 USDT를 포함해 잔고가 정확히 0이 됩니다. 수수료가 조금 더 들지만 주소나 네트워크 실수로 800 USDT 전체를 잃는 위험을 막을 수 있습니다."],"mistakes":["주소를 손으로 옮겨 적다가 한두 글자를 틀립니다.","거래 내역에 보이는 비슷한 주소를 복사해 주소 오염 공격에 당합니다.","메모나 태그가 필요한 코인에서 주소만 입력하고 메모를 빠뜨립니다."],"faq":[{"q":"지갑 주소를 알려 줘도 안전한가요?","a":"주소만으로는 자산을 옮길 수 없어 공유해도 됩니다. 다만 주소의 잔고와 거래 내역은 누구나 블록 익스플로러로 볼 수 있습니다."},{"q":"주소를 잘못 입력해 송금하면 돌려받을 수 있나요?","a":"블록체인 거래는 취소가 없어 일반적으로 돌려받기 어렵습니다. 받는 쪽이 거래소라면 문의할 수 있지만 복구 여부와 수수료는 거래소 정책에 따라 다릅니다."}],"title":"지갑 주소란? 입금 주소 뜻과 송금 전 확인법","description":"지갑 주소의 뜻, 체인별 주소 형식 차이, 잘못 송금하지 않기 위해 송금 전에 확인해야 할 점을 알려 드립니다.","related":[["blockchain-network","입금 네트워크(체인 선택)","입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다."],["memo-tag","메모·데스티네이션 태그(Memo/Tag)","메모(태그)는 거래소처럼 여러 사용자가 하나의 입금 주소를 함께 쓸 때 어느 계정의 입금인지 구분하기 위해 주소와 함께 입력하는 번호나 문자입니다."],["address-poisoning","주소 오염 공격(Address Poisoning)","주소 오염 공격은 내 주소와 앞뒤 글자가 비슷한 가짜 주소로 소액이나 0원 거래를 보내 거래 내역에 섞어 두고, 다음 송금 때 그 주소를 잘못 복사하게 만드는 사기입니다."],["withdrawal-whitelist","출금 화이트리스트(Withdrawal Whitelist)","출금 화이트리스트는 미리 등록하고 인증한 주소로만 출금할 수 있게 제한해, 계정이 탈취돼도 공격자 주소로 자산이 빠져나가지 못하게 하는 기능입니다."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"코인 전송 전: 이 항목들은 절대 어림짐작하지 마세요"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"ko","term":"피싱(Phishing)","aka":["피싱 사이트","피싱 사기","phishing"],"short":"피싱은 가짜 웹사이트, 메일, 메시지, 광고로 공식 서비스인 척 접근해 비밀번호, 시드 문구, 지갑 서명을 빼내는 사기 수법입니다.","body":[[["암호화폐","cryptocurrency"]," 피싱은 크게 세 가지 형태로 나타납니다. ",["거래소","centralized-exchange"]," 로그인 화면을 베낀 가짜 사이트로 비밀번호와 OTP를 받아 가는 방식, 지갑 복구나 ",["에어드랍","airdrop"],"을 핑계로 ",["시드 문구","seed-phrase"],"를 입력하게 하는 방식, 그리고 디앱 연결 화면에서 토큰 무제한 승인이나 위험한 서명을 하게 만드는 방식입니다."],"피싱 사이트는 검색 광고 상단, 유명 프로젝트의 가짜 X 계정 댓글, 디스코드와 텔레그램 공지 사칭으로 퍼지는 경우가 많습니다. 주소는 철자 하나만 다르거나 다른 도메인 확장자를 씁니다.","기본 방어는 공식 주소를 즐겨찾기로 저장해 그 경로로만 접속하는 것입니다. 지갑 서명 창이 뜨면 무엇을 승인하는지 읽고, 이해되지 않으면 거절하는 습관이 중요합니다."],"example":["새 토큰 에어드랍을 받으라는 X 댓글 링크를 눌러 지갑을 연결했다고 가정합니다. 사이트가 클레임 버튼과 함께 ",["USDT","usdt"]," 사용 승인을 요청하고, 사용자가 무심코 승인합니다. 이 승인은 사이트 계약에 USDT 무제한 사용 권한을 주는 것이어서, 지갑에 있던 4,200 USDT가 몇 분 뒤 전부 빠져나갑니다. 사용자는 송금 버튼을 누른 적이 없지만 승인 서명 한 번으로 충분했습니다."],"mistakes":["검색 결과 맨 위 광고 링크를 공식 사이트라고 믿고 로그인합니다.","지갑 서명 창의 내용을 읽지 않고 확인 버튼을 누릅니다.","관리자라며 먼저 DM을 보낸 사람의 안내를 따릅니다."],"faq":[{"q":"피싱 사이트에 지갑만 연결해도 돈이 빠져나가나요?","a":"단순 연결만으로는 보통 자산이 이동하지 않습니다. 문제는 연결 후 요청되는 토큰 승인이나 서명을 수락할 때 생기므로 서명 내용을 반드시 확인해야 합니다."},{"q":"피싱 사이트에 이미 서명했다면 무엇을 해야 하나요?","a":"토큰 승인 관리 도구에서 해당 승인을 즉시 취소하고, 남은 자산은 새 지갑으로 옮기는 것이 일반적입니다. 시드 문구를 입력했다면 그 지갑은 더 이상 쓰지 않아야 합니다."}],"title":"피싱이란? 코인 피싱 사이트 구별법","description":"암호화폐 피싱의 뜻과 대표 수법, 가짜 사이트와 위험한 지갑 서명을 구별하는 방법, 당했을 때 대처법을 정리합니다.","related":[["anti-phishing-code","피싱 방지 코드(Anti-phishing Code)","피싱 방지 코드는 사용자가 직접 정한 문구를 거래소가 공식 이메일에 함께 표시해, 그 문구가 없는 메일은 가짜임을 쉽게 알아보게 하는 보안 기능입니다."],["seed-phrase","시드 문구(Seed Phrase, 복구 문구)","시드 문구는 지갑을 만들 때 생성되는 12개 또는 24개의 영어 단어 목록으로, 이것만 있으면 지갑의 모든 개인 키와 자산을 복구할 수 있는 마스터 키입니다."],["token-approval","토큰 승인(Token Approval, 허용량)","토큰 승인은 스마트 컨트랙트가 내 지갑의 특정 토큰을 정해진 한도만큼 대신 옮길 수 있도록 허락하는 서명으로, 한 번 주면 취소하기 전까지 유지됩니다."],["address-poisoning","주소 오염 공격(Address Poisoning)","주소 오염 공격은 내 주소와 앞뒤 글자가 비슷한 가짜 주소로 소액이나 0원 거래를 보내 거래 내역에 섞어 두고, 다음 송금 때 그 주소를 잘못 복사하게 만드는 사기입니다."],["pig-butchering-scam","돼지 도살 사기(Pig Butchering Scam)","돼지 도살 사기는 SNS나 메신저로 친분이나 연애 감정을 쌓은 뒤 가짜 투자 플랫폼으로 유도해 점점 더 큰 돈을 넣게 하고 결국 출금을 막는 장기 사기입니다."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"진짜 문을 찾으세요: 무작정 계정을 만들지 마세요"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"ko","term":"준비금 증명(Proof of Reserves)","aka":["PoR","준비금 증명서","proof of reserves"],"short":"준비금 증명은 거래소가 고객이 맡긴 자산만큼의 코인을 실제로 보유하고 있는지 온체인 주소와 암호학적 방식으로 보여 주는 공개 검증 절차입니다.","body":[["2022년 대형 ",["거래소","centralized-exchange"]," 파산 이후 여러 거래소가 준비금 증명을 공개하기 시작했습니다. 보통 ",["거래소 지갑","custodial-wallet"]," 주소의 잔고를 공개하고, 고객 잔고 총합은 머클 트리라는 구조로 정리해 사용자가 자기 잔고가 포함됐는지 직접 확인할 수 있게 합니다."],"핵심 지표는 준비금 비율입니다. 고객 부채 대비 보유 자산이 100% 이상이면 장부상 고객 자산을 모두 감당할 수 있다는 뜻입니다. 코인별로 비율을 따로 공개하는 거래소도 있습니다.","한계도 분명합니다. 특정 시점의 스냅샷일 뿐이고, 거래소가 진 다른 부채를 모두 보여 주지는 않으며, 외부 감사 범위도 거래소마다 다릅니다. 거래소를 고를 때 참고 지표 중 하나로 보는 것이 적절합니다."],"example":["어떤 거래소가 ",["BTC","bitcoin"]," 고객 잔고 합계 10,000 BTC, 공개 지갑 보유량 10,400 BTC를 공개했다고 가정합니다. 준비금 비율은 10,400 나누기 10,000으로 104%입니다. 내 계정에 0.25 BTC가 있다면 머클 트리 검증 도구에 내 기록 ID를 입력해 0.25 BTC가 합계에 포함됐는지 확인할 수 있습니다. 다만 이 수치는 스냅샷 시점 기준이며, 다음 날 지갑에서 자산이 빠져나가도 다음 공개 전까지는 알 수 없습니다."],"mistakes":["준비금 비율 100% 이상이면 거래소가 절대 망하지 않는다고 생각합니다.","공개 날짜를 확인하지 않고 오래된 증명 자료를 최신 정보로 믿습니다.","내 잔고가 머클 트리에 포함됐는지 직접 확인할 수 있다는 사실을 모릅니다."],"faq":[{"q":"준비금 증명이 있으면 거래소는 안전한가요?","a":"고객 자산을 보유하고 있다는 근거는 되지만 부채 전체, 운영 리스크, 해킹 위험까지 보여 주지는 않습니다. 여러 지표 중 하나로 활용해야 합니다."},{"q":"준비금 비율은 얼마가 적당한가요?","a":"최소 100% 이상이어야 고객 잔고를 모두 감당할 수 있다는 뜻입니다. 코인별 비율과 공개 주기, 외부 검증 여부도 함께 보는 것이 좋습니다."}],"title":"준비금 증명(PoR)이란? 거래소 자산 확인법","description":"거래소 준비금 증명(PoR)의 뜻, 준비금 비율과 머클 트리로 내 잔고를 확인하는 방법, 이 지표의 한계를 설명합니다.","related":[["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다."],["custodial-wallet","수탁형 지갑(Custodial Wallet)","수탁형 지갑은 거래소나 서비스 업체가 개인 키를 대신 보관하고 관리하는 지갑으로, 이용자는 아이디와 비밀번호로 접근하지만 코인의 직접 통제권은 업체에 있습니다."],["insurance-fund","보험 기금(Insurance Fund)","보험 기금은 강제청산된 포지션이 파산 가격보다 나쁜 가격에 정리될 때 생기는 손실을 메우기 위해 선물 거래소가 별도로 쌓아 두는 자금입니다."],["on-chain-analysis","온체인 분석","온체인 분석은 블록체인에 공개 기록된 거래, 주소, 잔고 데이터를 읽어 자금 흐름과 네트워크 사용 현황을 파악하는 분석 방법입니다."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"진짜 문을 찾으세요: 무작정 계정을 만들지 마세요"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"ko","term":"거래소 예치 상품(Crypto Earn)","aka":["언 상품","코인 예치","Earn","Simple Earn"],"short":"거래소 예치 상품은 거래소에 코인을 맡기면 정해진 기간이나 자유 입출금 조건으로 이자 성격의 보상을 주는 상품군을 말합니다.","body":[[["거래소","centralized-exchange"],"마다 Earn, Simple Earn, 저축 같은 이름으로 부릅니다. 언제든 빼는 자유형과 기간을 묶는 고정형이 기본이며, 그 뒤에서 거래소는 맡긴 코인을 ",["스테이킹","staking"],"하거나 대출 시장에 빌려주거나 ",["디파이","defi"],"에 운용해 수익을 만듭니다. 상품에 따라 ",["이중 투자","dual-investment"],"처럼 구조화 상품이 같은 메뉴에 섞여 있기도 합니다."],["보상률은 보통 ",["연이율","apr-vs-apy"],"(APR)로 표시되며 시장 수요에 따라 수시로 바뀝니다. 고정형은 만기 전에 해지하면 보상을 받지 못하거나 원금 일부만 즉시 돌려받는 조건이 있을 수 있습니다. 첫 구간 금액에만 높은 이율을 주는 단계형 이율도 흔합니다."],"가장 중요한 점은 코인을 거래소에 맡긴다는 것입니다. 거래소가 운용에 실패하거나 지급 불능이 되면 보상뿐 아니라 원금도 위험해질 수 있습니다. 2022년 일부 대출 플랫폼의 출금 중단 사태가 그 예입니다."],"example":[["USDT","usdt"]," 5,000개를 자유형 상품에 넣었는데 첫 500 USDT까지는 연 8%, 나머지는 연 3%라고 가정합니다. 1년 보상은 500 × 8% = 40 USDT와 4,500 × 3% = 135 USDT를 합쳐 175 USDT입니다. 전체 기준 실제 이율은 3.5%입니다. 광고된 8%만 보고 400 USDT를 기대했다면 계산이 크게 빗나갑니다. 이율 수치는 예시이며 실제 조건은 상품마다 다릅니다."],"mistakes":["단계형 이율에서 가장 높은 숫자가 전체 금액에 적용된다고 생각합니다.","고정형 상품의 중도 해지 조건을 확인하지 않고 급한 자금을 넣습니다.","거래소 예치 상품을 은행 예금처럼 원금이 보호된다고 여깁니다."],"faq":[{"q":"거래소 예치 상품의 이자는 어디서 나오나요?","a":"스테이킹 보상, 레버리지 거래자에게 빌려준 이자, 디파이 운용 수익 등에서 나옵니다. 상품 설명에서 운용 방식을 확인할 수 있습니다."},{"q":"APR과 APY는 어떻게 다른가요?","a":"APR은 복리를 반영하지 않은 연이율이고, APY는 보상을 다시 넣는 복리 효과를 반영한 연수익률입니다."}],"title":"거래소 예치 상품(Earn)이란? 이자 구조와 위험","description":"거래소 예치 상품의 뜻, 자유형·고정형 차이, 단계형 이율의 실제 수익 계산과 원금 위험을 설명합니다.","related":[["staking","스테이킹(Staking)","스테이킹은 지분증명(PoS) 블록체인에서 코인을 맡겨 네트워크 검증에 참여하거나 검증인에게 위임하고 그 대가로 보상을 받는 방법입니다."],["apr-vs-apy","APR과 APY의 차이","APR은 복리를 반영하지 않은 단순 연이율이고, APY는 받은 이자를 다시 굴리는 복리 효과까지 반영한 연 수익률입니다."],["dual-investment","이중 투자(Dual investment)","이중 투자는 목표 가격과 만기를 정해 코인이나 스테이블코인을 맡기면, 만기 시 가격에 따라 원래 자산 또는 다른 자산으로 원금과 보상을 돌려받는 구조화 상품입니다."],["custodial-wallet","수탁형 지갑(Custodial Wallet)","수탁형 지갑은 거래소나 서비스 업체가 개인 키를 대신 보관하고 관리하는 지갑으로, 이용자는 아이디와 비밀번호로 접근하지만 코인의 직접 통제권은 업체에 있습니다."]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"ko","term":"P2P 거래(C2C)","aka":["P2P","C2C 거래","개인 간 거래","P2P trading"],"short":"P2P 거래는 거래소가 중개하는 게시판에서 개인끼리 은행 이체 등 법정화폐로 대금을 주고받고 USDT 같은 코인을 사고파는 방식입니다.","body":[["판매자는 가격, 수량, 결제 수단을 걸어 광고를 올리고, 구매자가 주문하면 ",["거래소","centralized-exchange"],"가 판매자의 코인을 에스크로로 묶어 둡니다. 구매자가 은행 이체로 대금을 보내고 판매자가 입금을 확인해 코인을 풀어 주면 거래가 끝납니다. 분쟁이 생기면 거래소 고객센터가 개입합니다."],"은행과 직접 연결되지 않은 해외 거래소에서 법정화폐로 코인을 살 때 쓰이는 대표적인 경로입니다. 가격은 판매자가 정하므로 시장 가격보다 조금 높은 경우가 많고, 결제 수단과 한도, 판매자 거래 실적에 따라 차이가 납니다.","가장 큰 위험은 결제 단계입니다. 판매자는 실제로 돈이 들어왔는지 은행 앱에서 확인하기 전에 코인을 풀면 안 되고, 구매자는 거래소 채팅 밖으로 대화를 옮기자는 요청에 응하면 안 됩니다. 범죄 피해금이 섞인 입금으로 계좌가 정지되는 일도 있어 입금자명 확인이 중요합니다."],"example":["P2P 게시판에서 1 USDT를 1,420원에 파는 판매자에게 500 USDT를 사려 한다고 가정합니다. 송금할 금액은 710,000원입니다. 같은 시각 시장 기준 가격이 1,400원이라면 10,000원, 약 1.4%를 더 내는 셈입니다. 대금은 거래 화면에 표시된 판매자 명의 계좌로만 보내고, 입금 메모에 코인이나 ",["USDT","usdt"]," 같은 단어를 쓰지 말라는 요청이 있으면 판매자 정책을 확인합니다. 송금 후에는 반드시 송금 완료 버튼을 눌러야 에스크로가 진행됩니다."],"mistakes":["판매자가 은행 앱에서 입금을 확인하기 전에 입금 확인 문자만 보고 코인을 풀어 줍니다.","거래소 채팅 대신 메신저로 옮겨 거래를 진행합니다.","판매자 계정 이름과 다른 명의의 계좌로 대금을 보냅니다."],"faq":[{"q":"P2P 거래에서 돈을 보냈는데 코인을 못 받았어요.","a":"송금 완료 버튼을 눌렀는지 확인하고, 거래 화면에서 이의 제기를 신청하세요. 코인은 에스크로에 묶여 있으므로 증빙을 제출하면 고객센터가 처리합니다."},{"q":"P2P와 C2C는 같은 말인가요?","a":"대부분의 거래소에서 같은 서비스를 가리킵니다. 거래소에 따라 P2P 또는 C2C라는 이름을 씁니다."}],"title":"P2P 거래(C2C)란? 개인 간 코인 거래 방법과 주의점","description":"P2P(C2C) 거래의 뜻, 에스크로 진행 순서, 가격 차이 계산과 사기·계좌 정지를 피하는 법을 설명합니다.","related":[["fiat-on-ramp","법정화폐 온램프(Fiat on-ramp)","법정화폐 온램프는 원화나 달러 같은 법정화폐를 암호화폐로 바꿔 시장에 처음 들어오는 경로로, 거래소 입금, 카드 결제, P2P 거래 등이 있습니다."],["usdt","USDT(테더)","USDT(테더)는 테더(Tether)사가 발행하는 미국 달러 연동 스테이블코인으로, 거래량과 시가총액 기준 가장 큰 스테이블코인입니다."],["pig-butchering-scam","돼지 도살 사기(Pig Butchering Scam)","돼지 도살 사기는 SNS나 메신저로 친분이나 연애 감정을 쌓은 뒤 가짜 투자 플랫폼으로 유도해 점점 더 큰 돈을 넣게 하고 결국 출금을 막는 장기 사기입니다."],["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"첫 입금: 돈은 어디서 들어오고 어디로 가는 걸까요?"},"coin":null,"tool":null,"cta":true}});
